insert into public.diagnostic_questions(id,question_text,category,subcategory,difficulty,option_a,option_b,option_c,option_d,correct_answer,explanation,estimated_time_seconds,active) select id,question_text,category,subcategory,difficulty,option_a,option_b,option_c,option_d,correct_answer,explanation,estimated_time_seconds,true from jsonb_to_recordset($diagnostic$[{"id":"tech2-1","category":"database_technical","subcategory":"Programming","question_text":"What is the purpose of a variable?","options":["To connect a computer to the internet","To design a database index","To store a value that a program can use","To encrypt every file"],"correct_answer":"C","explanation":"A variable names a storage location or value used by a program.","estimated_time_seconds":60,"difficulty":1,"option_a":"To connect a computer to the internet","option_b":"To design a database index","option_c":"To store a value that a program can use","option_d":"To encrypt every file"},{"id":"tech2-2","category":"database_technical","subcategory":"Programming","question_text":"Which control structure repeats a block of code?","options":["A comment","A constant","An import","A loop"],"correct_answer":"D","explanation":"Loops repeat instructions while their continuation condition permits.","estimated_time_seconds":60,"difficulty":1,"option_a":"A comment","option_b":"A constant","option_c":"An import","option_d":"A loop"},{"id":"tech2-3","category":"database_technical","subcategory":"Programming","question_text":"What does a function primarily provide?","options":["A reusable block of behavior","A permanent network address","A database backup","A visual color theme"],"correct_answer":"A","explanation":"Functions package behavior behind a callable name and parameters.","estimated_time_seconds":60,"difficulty":2,"option_a":"A reusable block of behavior","option_b":"A permanent network address","option_c":"A database backup","option_d":"A visual color theme"},{"id":"tech2-4","category":"database_technical","subcategory":"Programming","question_text":"What is a Boolean value?","options":["A decimal number only","A value that is true or false","A text file","A database row"],"correct_answer":"B","explanation":"Boolean values represent two logical states.","estimated_time_seconds":60,"difficulty":2,"option_a":"A decimal number only","option_b":"A value that is true or false","option_c":"A text file","option_d":"A database row"},{"id":"tech2-5","category":"database_technical","subcategory":"Programming","question_text":"What does an array normally store?","options":["Only one Boolean value","A network connection","An ordered collection of values","A compiled application"],"correct_answer":"C","explanation":"An array groups values in an ordered structure.","estimated_time_seconds":60,"difficulty":2,"option_a":"Only one Boolean value","option_b":"A network connection","option_c":"An ordered collection of values","option_d":"A compiled application"},{"id":"tech2-6","category":"database_technical","subcategory":"Algorithms","question_text":"What does binary search require?","options":["A random password","A graphical interface","An unsaved file","A sorted search space"],"correct_answer":"D","explanation":"Binary search repeatedly halves a sorted search range.","estimated_time_seconds":60,"difficulty":2,"option_a":"A random password","option_b":"A graphical interface","option_c":"An unsaved file","option_d":"A sorted search space"},{"id":"tech2-7","category":"database_technical","subcategory":"Algorithms","question_text":"What is the time complexity of linear search in the worst case?","options":["O(n)","O(1)","O(log n)","O(n squared) for every input"],"correct_answer":"A","explanation":"Linear search may inspect each of n elements once.","estimated_time_seconds":60,"difficulty":2,"option_a":"O(n)","option_b":"O(1)","option_c":"O(log n)","option_d":"O(n squared) for every input"},{"id":"tech2-8","category":"database_technical","subcategory":"Data Structures","question_text":"Which data structure follows last-in, first-out order?","options":["Queue","Stack","Graph","Hash set"],"correct_answer":"B","explanation":"A stack removes the most recently added item first.","estimated_time_seconds":60,"difficulty":3,"option_a":"Queue","option_b":"Stack","option_c":"Graph","option_d":"Hash set"},{"id":"tech2-9","category":"database_technical","subcategory":"Data Structures","question_text":"Which data structure follows first-in, first-out order?","options":["Stack","Tree","Queue","Recursion"],"correct_answer":"C","explanation":"A queue removes items in their arrival order.","estimated_time_seconds":60,"difficulty":3,"option_a":"Stack","option_b":"Tree","option_c":"Queue","option_d":"Recursion"},{"id":"tech2-10","category":"database_technical","subcategory":"Data Structures","question_text":"What does a hash table primarily use to locate values?","options":["A sorted linked list only","A screen coordinate","A network port","A hash-derived key position"],"correct_answer":"D","explanation":"Hashing maps keys to storage positions for efficient lookup.","estimated_time_seconds":60,"difficulty":3,"option_a":"A sorted linked list only","option_b":"A screen coordinate","option_c":"A network port","option_d":"A hash-derived key position"},{"id":"tech2-11","category":"database_technical","subcategory":"Object-Oriented Programming","question_text":"What is encapsulation?","options":["Keeping data and related behavior behind a controlled interface","Copying every object","Running code in parallel","Converting text to numbers"],"correct_answer":"A","explanation":"Encapsulation controls access to an object's internal state.","estimated_time_seconds":60,"difficulty":1,"option_a":"Keeping data and related behavior behind a controlled interface","option_b":"Copying every object","option_c":"Running code in parallel","option_d":"Converting text to numbers"},{"id":"tech2-12","category":"database_technical","subcategory":"Object-Oriented Programming","question_text":"What is inheritance used for?","options":["Deleting parent records","Deriving a type from an existing type","Encrypting source code","Sorting an array"],"correct_answer":"B","explanation":"Inheritance lets a derived type reuse or extend behavior.","estimated_time_seconds":60,"difficulty":1,"option_a":"Deleting parent records","option_b":"Deriving a type from an existing type","option_c":"Encrypting source code","option_d":"Sorting an array"},{"id":"tech2-13","category":"database_technical","subcategory":"Object-Oriented Programming","question_text":"What is polymorphism?","options":["Storing only one data type","Preventing every override","Using a common interface with different implementations","Running one statement once"],"correct_answer":"C","explanation":"Polymorphism allows different types to respond through a shared contract.","estimated_time_seconds":60,"difficulty":2,"option_a":"Storing only one data type","option_b":"Preventing every override","option_c":"Using a common interface with different implementations","option_d":"Running one statement once"},{"id":"tech2-14","category":"database_technical","subcategory":"Testing","question_text":"What does a unit test normally verify?","options":["An entire country's network","Only visual colors","A production database backup","A small isolated unit of behavior"],"correct_answer":"D","explanation":"Unit tests focus on a small function, class, or component.","estimated_time_seconds":60,"difficulty":2,"option_a":"An entire country's network","option_b":"Only visual colors","option_c":"A production database backup","option_d":"A small isolated unit of behavior"},{"id":"tech2-15","category":"database_technical","subcategory":"Testing","question_text":"What is a regression test intended to detect?","options":["A previously working behavior that has broken","A faster network cable","A new employee record","A stronger password"],"correct_answer":"A","explanation":"Regression tests guard behavior that worked before a change.","estimated_time_seconds":60,"difficulty":2,"option_a":"A previously working behavior that has broken","option_b":"A faster network cable","option_c":"A new employee record","option_d":"A stronger password"},{"id":"tech2-16","category":"database_technical","subcategory":"Version Control","question_text":"What does a Git commit represent?","options":["A deleted repository","A recorded snapshot of staged changes","A live database transaction","A web browser cookie"],"correct_answer":"B","explanation":"A commit records a versioned snapshot and its metadata.","estimated_time_seconds":60,"difficulty":2,"option_a":"A deleted repository","option_b":"A recorded snapshot of staged changes","option_c":"A live database transaction","option_d":"A web browser cookie"},{"id":"tech2-17","category":"database_technical","subcategory":"Version Control","question_text":"What is the purpose of a Git branch?","options":["To store database rows","To host an HTTP request","To develop an independent line of changes","To compile Java bytecode"],"correct_answer":"C","explanation":"Branches let work evolve independently before integration.","estimated_time_seconds":60,"difficulty":2,"option_a":"To store database rows","option_b":"To host an HTTP request","option_c":"To develop an independent line of changes","option_d":"To compile Java bytecode"},{"id":"tech2-18","category":"database_technical","subcategory":"HTTP","question_text":"Which HTTP method is normally used to retrieve a resource?","options":["POST","DELETE","PATCH","GET"],"correct_answer":"D","explanation":"GET requests a representation without intending a state change.","estimated_time_seconds":60,"difficulty":3,"option_a":"POST","option_b":"DELETE","option_c":"PATCH","option_d":"GET"},{"id":"tech2-19","category":"database_technical","subcategory":"HTTP","question_text":"Which status code means a resource was not found?","options":["404","200","201","500"],"correct_answer":"A","explanation":"HTTP 404 indicates that the requested resource was not found.","estimated_time_seconds":60,"difficulty":3,"option_a":"404","option_b":"200","option_c":"201","option_d":"500"},{"id":"tech2-20","category":"database_technical","subcategory":"HTTP","question_text":"Which status-code range represents server errors?","options":["100 to 199","500 to 599","200 to 299","300 to 399"],"correct_answer":"B","explanation":"The 5xx class reports server-side failures.","estimated_time_seconds":60,"difficulty":3,"option_a":"100 to 199","option_b":"500 to 599","option_c":"200 to 299","option_d":"300 to 399"},{"id":"tech2-21","category":"database_technical","subcategory":"Web","question_text":"What is HTML primarily used for?","options":["Encrypting database passwords","Compiling operating systems","Structuring web-page content","Routing network packets"],"correct_answer":"C","explanation":"HTML describes the structure and semantics of web content.","estimated_time_seconds":60,"difficulty":1,"option_a":"Encrypting database passwords","option_b":"Compiling operating systems","option_c":"Structuring web-page content","option_d":"Routing network packets"},{"id":"tech2-22","category":"database_technical","subcategory":"Web","question_text":"What is CSS primarily used for?","options":["Executing database transactions","Creating encryption keys","Managing Git history","Styling and laying out web content"],"correct_answer":"D","explanation":"CSS controls presentation and layout.","estimated_time_seconds":60,"difficulty":1,"option_a":"Executing database transactions","option_b":"Creating encryption keys","option_c":"Managing Git history","option_d":"Styling and laying out web content"},{"id":"tech2-23","category":"database_technical","subcategory":"Web","question_text":"What is JavaScript commonly used for in a browser?","options":["Adding behavior and interactivity","Replacing every web server","Creating physical networks","Formatting disk partitions"],"correct_answer":"A","explanation":"Browser JavaScript responds to events and updates page behavior.","estimated_time_seconds":60,"difficulty":2,"option_a":"Adding behavior and interactivity","option_b":"Replacing every web server","option_c":"Creating physical networks","option_d":"Formatting disk partitions"},{"id":"tech2-24","category":"database_technical","subcategory":"APIs","question_text":"What does JSON represent?","options":["A compiled machine instruction","Structured data using objects, arrays, and primitive values","An image compression format only","A database lock"],"correct_answer":"B","explanation":"JSON is a text format for structured data exchange.","estimated_time_seconds":60,"difficulty":2,"option_a":"A compiled machine instruction","option_b":"Structured data using objects, arrays, and primitive values","option_c":"An image compression format only","option_d":"A database lock"},{"id":"tech2-25","category":"database_technical","subcategory":"APIs","question_text":"What does REST commonly model URLs as?","options":["CPU instructions","Spreadsheet formulas","Resources acted on through HTTP methods","Encryption certificates"],"correct_answer":"C","explanation":"REST-style APIs expose resources and use HTTP semantics.","estimated_time_seconds":60,"difficulty":2,"option_a":"CPU instructions","option_b":"Spreadsheet formulas","option_c":"Resources acted on through HTTP methods","option_d":"Encryption certificates"}]$diagnostic$::jsonb) as x(id text,question_text text,category text,subcategory text,difficulty numeric,option_a text,option_b text,option_c text,option_d text,correct_answer char(1),explanation text,estimated_time_seconds integer) on conflict(id) do update set question_text=excluded.question_text,category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,option_a=excluded.option_a,option_b=excluded.option_b,option_c=excluded.option_c,option_d=excluded.option_d,correct_answer=excluded.correct_answer,explanation=excluded.explanation,estimated_time_seconds=excluded.estimated_time_seconds,active=true;
